//! Audio request and response bodies (architecture.md §5.3, §7).

use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

/// Where the clip should come from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "snake_case")]
pub enum AudioSource {
    /// Generated by the text-to-speech provider.
    Tts,
    /// A native speaker's recording from Wikimedia Commons.
    Commons,
}

#[derive(Debug, Deserialize, ToSchema)]
pub struct AttachAudioRequest {
    pub source: AudioSource,
    /// TTS voice name (e.g. `en-GB-RyanNeural`); default: the voice of the deck's language.
    pub voice: Option<String>,
}

#[derive(Debug, Serialize, Deserialize, ToSchema)]
pub struct AttachAudioResponse {
    /// The new `cards.audio_id`; the clip is at `GET /api/audio/{audio_id}`.
    pub audio_id: String,
    /// Author and license of a recording; `null` for generated audio.
    pub attribution: Option<String>,
}
